1	import { useMemo, useState } from "react";
2	import { useMutation, useQueryClient } from "@tanstack/react-query";
3	import { usePropertyInvoices, usePropertyTenants, PROPERTY_KEYS } from "@/lib/property-data";
4	import { propHeaders } from "@/lib/property-api";
5	import { notifyIfBillingCardRequired } from "@/lib/queryClient";
6	import { useToast } from "@/hooks/use-toast";
7	import { fmtNZD } from "@/lib/report-utils";
8	import {
9	  DesktopPageScaffold,
10	  type DesktopRoutePageProps,
11	} from "../DesktopPageScaffold";
12	import {
13	  DESKTOP_KEYPAD_KEYS,
14	  DesktopKeypadButton,
15	  desktopKeypadCents,
16	  desktopKeypadReducer,
17	  formatDesktopKeypadMoney,
18	  type DesktopKeypadKey,
19	} from "../desktop-keypad";
20	
21	/* ── palette ── */
22	const ACCENT = "#5E9EFF";
23	const ACCENT_SOFT = "#7FB2FF";
24	const NAV_DIM = "#4A86F0";
25	const ACTIVE = "#66A9FF";
26	const TEXT_SOFT = "#F4F6FF";
27	const NAVY = "#000F3F";
28	const INK = "#12162E";
29	const KP_INK = "#C6CFE2";
30	const VIOLET = "#9DBCFF";
31	const GREEN = "#35D07F";
32	const RED = "#F0656C";
33	const AMBER = "#F0A34E";
34	
35	type Mode = "tenant" | "request" | "keypad" | "bill" | "paid";
36	
37	/* Charge types and frequency handling mirror property-terminal.tsx exactly. */
38	const CHARGE_TYPES = [
39	  { id: "utilities", label: "water / utilities", preset: "Water / utilities" },
40	  { id: "late_fee", label: "late fee", preset: "Late fee" },
41	  { id: "cleaning", label: "cleaning", preset: "Cleaning" },
42	  { id: "damages", label: "damages", preset: "Damages" },
43	  { id: "other", label: "other", preset: "" },
44	];
45	
46	const FREQUENCIES = ["once", "weekly", "fortnightly", "monthly"] as const;
47	type Frequency = (typeof FREQUENCIES)[number];
48	const FREQ_LABEL: Record<Frequency, string> = {
49	  once: "one-off",
50	  weekly: "per week",
51	  fortnightly: "per fortnight",
52	  monthly: "per month",
53	};
54	
55	const STACK_FILTERS = ["all", "overdue", "sent", "paid", "failed"] as const;
56	type StackFilter = (typeof STACK_FILTERS)[number];
57	
58	function addInterval(from: Date, frequency: string): Date {
59	  const d = new Date(from);
60	  if (frequency === "weekly") d.setDate(d.getDate() + 7);
61	  else if (frequency === "fortnightly") d.setDate(d.getDate() + 14);
62	  else d.setMonth(d.getMonth() + 1);
63	  return d;
64	}
65	
66	const initialsOf = (t: any) =>
67	  `${t?.firstName?.[0] ?? ""}${t?.lastName?.[0] ?? ""}`.toUpperCase() || "?";
68	const fullNameOf = (t: any) => `${t?.firstName ?? ""} ${t?.lastName ?? ""}`.trim() || "tenant";
69	const whole = (cents: number) => "$" + Math.round(cents / 100).toLocaleString("en-NZ");
70	
71	/* The design's list buckets, mapped onto real invoice statuses. */
72	function bucketOf(status: string): Exclude<StackFilter, "all"> {
73	  if (status === "paid" || status === "paid_external") return "paid";
74	  if (status === "overdue") return "overdue";
75	  if (status === "dispatch_failed" || status === "failed") return "failed";
76	  return "sent";
77	}
78	
79	const STATUS_DOT: Record<string, string> = {
80	  overdue: AMBER,
81	  sent: ACCENT,
82	  paid: GREEN,
83	  failed: RED,
84	};
85	
86	export default function DesktopPropertyTerminal(props: DesktopRoutePageProps) {
87	  const queryClient = useQueryClient();
88	  const { toast } = useToast();
89	
90	  const [mode, setMode] = useState<Mode>("request");
91	  const [tenantId, setTenantId] = useState<string | null>(null);
92	  const [amountCents, setAmountCents] = useState(0);
93	  const [kpVal, setKpVal] = useState("");
94	  const [frequency, setFrequency] = useState<Frequency>("once");
95	  const [chargeType, setChargeType] = useState("utilities");
96	  const [description, setDescription] = useState("Water / utilities");
97	  const [search, setSearch] = useState("");
98	  const [tenantSearch, setTenantSearch] = useState("");
99	  const [filter, setFilter] = useState<StackFilter>("all");
100	  const [reqFlash, setReqFlash] = useState(false);
101	  const [billFlash, setBillFlash] = useState(false);
102	
103	  const tenantsQuery = usePropertyTenants();
104	  const invoicesQuery = usePropertyInvoices();
105	  const tenants = (tenantsQuery.data ?? []).filter((t: any) => t.status !== "archived");
106	  const invoices = invoicesQuery.data ?? [];
107	
108	  const tenant = tenants.find((t: any) => t.id === tenantId) ?? null;
109	  const channel = (tenant?.preferredChannel ?? "email") as string;
110	  const channelContact = channel === "email" ? tenant?.email : tenant?.phone;
111	
112	  /* ── left column figures + request list ── */
113	  const model = useMemo(() => {
114	    const live = invoices.filter((i: any) => i.status !== "voided");
115	    const unpaid = live.filter((i: any) => i.status !== "paid" && i.status !== "paid_external");
116	    const outstandingRent = unpaid
117	      .filter((i: any) => (i.kind ?? "rent") === "rent")
118	      .reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
119	    const outstandingExpenses = unpaid
120	      .filter((i: any) => i.kind === "charge")
121	      .reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
122	
123	    const byId = new Map(tenants.map((t: any) => [t.id, t]));
124	    const rows = [...live]
125	      .sort(
126	        (a: any, b: any) =>
127	          new Date(b.createdAt ?? b.dueAt).getTime() - new Date(a.createdAt ?? a.dueAt).getTime(),
128	      )
129	      .map((i: any) => {
130	        const t = byId.get(i.tenantProfileId);
131	        const bucket = bucketOf(i.status);
132	        return {
133	          id: i.id as string,
134	          name: t ? fullNameOf(t) : "tenant",
135	          initials: t ? initialsOf(t) : "?",
136	          bucket,
137	          status:
138	            bucket === "paid"
139	              ? i.status === "paid_external"
140	                ? "paid · marked"
141	                : "paid"
142	              : bucket === "overdue"
143	                ? "overdue"
144	                : bucket === "failed"
145	                  ? "delivery failed"
146	                  : (i.kind ?? "rent") === "charge"
147	                    ? `sent · ${i.chargeType ?? "charge"}`
148	                    : "sent",
149	          amt: fmtNZD(i.amountCents ?? 0),
150	        };
151	      });
152	
153	    return { outstandingRent, outstandingExpenses, rows };
154	  }, [invoices, tenants]);
155	
156	  const q = search.trim().toLowerCase();
157	  const stackRows = model.rows
158	    .filter((r) => filter === "all" || r.bucket === filter)
159	    .filter((r) => r.name.toLowerCase().includes(q));
160	
161	  const tenantCards = tenants.filter((t: any) =>
162	    `${fullNameOf(t)} ${t.propertyAddress ?? ""}`
163	      .toLowerCase()
164	      .includes(tenantSearch.trim().toLowerCase()),
165	  );
166	
167	  const nextUnpaidFor = (id: string) =>
168	    invoices
169	      .filter(
170	        (i: any) =>
171	          i.tenantProfileId === id &&
172	          i.status !== "voided" &&
173	          i.status !== "paid" &&
174	          i.status !== "paid_external",
175	      )
176	      .sort((a: any, b: any) => new Date(a.dueAt).getTime() - new Date(b.dueAt).getTime())[0];
177	
178	  /* ── mutations: same endpoints and payloads as the mobile terminal ── */
179	  const sendRequest = useMutation({
180	    mutationFn: async () => {
181	      const now = new Date();
182	      const due = new Date(now);
183	      due.setDate(due.getDate() + 7);
184	      const res = await fetch("/api/property/invoices", {
185	        method: "POST",
186	        headers: { "Content-Type": "application/json", ...propHeaders() },
187	        body: JSON.stringify({
188	          tenantProfileId: tenantId,
189	          amountCents,
190	          deliveryChannel: channel,
191	          dueAt: due.toISOString(),
192	          splitEnabled: false,
193	        }),
194	      });
195	      if (!res.ok) {
196	        notifyIfBillingCardRequired(res);
197	        const message = await res
198	          .json()
199	          .then((d: any) => d.message)
200	          .catch(() => "Failed to send");
201	        throw new Error(message);
202	      }
203	      const invoice = await res.json();
204	      /* Recurring: first request goes now, automation starts one interval on. */
205	      if (frequency !== "once") {
206	        const startDate = addInterval(now, frequency);
207	        const sr = await fetch(`/api/property/tenants/${tenantId}/schedules`, {
208	          method: "POST",
209	          headers: { "Content-Type": "application/json", ...propHeaders() },
210	          body: JSON.stringify({
211	            amountCents,
212	            frequency,
213	            deliveryChannel: channel,
214	            startDate: startDate.toISOString(),
215	          }),
216	        });
217	        if (!sr.ok) {
218	          notifyIfBillingCardRequired(sr);
219	          throw new Error("Sent, but failed to set up automation");
220	        }
221	      }
222	      return invoice;
223	    },
224	    onSuccess: () => {
225	      queryClient.invalidateQueries({ queryKey: PROPERTY_KEYS.invoices as any });
226	      if (frequency !== "once") {
227	        queryClient.invalidateQueries({ queryKey: PROPERTY_KEYS.schedules as any });
228	      }
229	      setReqFlash(true);
230	      setTimeout(() => setReqFlash(false), 1600);
231	      setFrequency("once");
232	    },
233	    onError: (e: any) => toast({ title: e?.message || "Failed to send", variant: "destructive" }),
234	  });
235	
236	  const sendBill = useMutation({
237	    mutationFn: async () => {
238	      const res = await fetch("/api/property/invoices", {
239	        method: "POST",
240	        headers: { "Content-Type": "application/json", ...propHeaders() },
241	        body: JSON.stringify({
242	          tenantProfileId: tenantId,
243	          amountCents,
244	          deliveryChannel: channel,
245	          dueAt: new Date().toISOString(),
246	          splitEnabled: false,
247	          kind: "charge",
248	          chargeType,
249	          description,
250	        }),
251	      });
252	      if (!res.ok) {
253	        notifyIfBillingCardRequired(res);
254	        const message = await res
255	          .json()
256	          .then((d: any) => d.message)
257	          .catch(() => "Failed to send bill");
258	        throw new Error(message);
259	      }
260	      return res.json();
261	    },
262	    onSuccess: () => {
263	      queryClient.invalidateQueries({ queryKey: PROPERTY_KEYS.invoices as any });
264	      setBillFlash(true);
265	      setTimeout(() => setBillFlash(false), 1600);
266	    },
267	    onError: (e: any) =>
268	      toast({ title: e?.message || "Failed to send bill", variant: "destructive" }),
269	  });
270	
271	  const markPaid = useMutation({
272	    mutationFn: async (invoiceId: string) => {
273	      const res = await fetch(`/api/property/invoices/${invoiceId}/mark-paid-external`, {
274	        method: "POST",
275	        headers: { "Content-Type": "application/json", ...propHeaders() },
276	        body: JSON.stringify({ externalPaymentReference: null }),
277	      });
278	      if (!res.ok) throw new Error("Failed to mark");
279	      return res.json();
280	    },
281	    onSuccess: () => {
282	      queryClient.invalidateQueries({ queryKey: PROPERTY_KEYS.invoices as any });
283	      toast({ title: "Marked as received" });
284	    },
285	    onError: () => toast({ title: "Failed to mark as paid", variant: "destructive" }),
286	  });
287	
288	  /* ── actions ── */
289	  const requireTenant = () => {
290	    if (!tenant) {
291	      toast({ title: "Pick a tenant first", variant: "destructive" });
292	      setMode("tenant");
293	      return false;
294	    }
295	    return true;
296	  };
297	
298	  const doSendRequest = () => {
299	    if (!requireTenant()) return;
300	    if (amountCents <= 0) {
301	      toast({ title: "Enter an amount first", variant: "destructive" });
302	      setMode("keypad");
303	      return;
304	    }
305	    if (!channelContact) {
306	      toast({
307	        title: `No ${channel} on file for ${fullNameOf(tenant)}`,
308	        description: "Add one on their profile before sending.",
309	        variant: "destructive",
310	      });
311	      return;
312	    }
313	    sendRequest.mutate();
314	  };
315	
316	  const doSendBill = () => {
317	    if (!requireTenant()) return;
318	    if (amountCents <= 0) {
319	      toast({ title: "Enter an amount first", variant: "destructive" });
320	      setMode("keypad");
321	      return;
322	    }
323	    if (!description.trim()) {
324	      toast({ title: "Describe what the bill is for", variant: "destructive" });
325	      return;
326	    }
327	    sendBill.mutate();
328	  };
329	
330	  const pressKey = (key: DesktopKeypadKey) =>
331	    setKpVal((value) => desktopKeypadReducer(value, key));
332	
333	  const openKeypad = () => {
334	    setKpVal("");
335	    setMode("keypad");
336	  };
337	
338	  const railBtn = (m: Mode, big: boolean, path: JSX.Element, label: string) => {
339	    const on = mode === m;
340	    return (
341	      <button
342	        type="button"
343	        className={big ? "pt-rail-btn pt-rail-big" : "pt-rail-btn"}
344	        aria-label={label}
345	        aria-pressed={on}
346	        style={big ? undefined : { background: on ? ACTIVE : "transparent" }}
347	        onClick={() => (big ? openKeypad() : setMode(m))}
348	      >
349	        <svg
350	          width={big ? 24 : 19}
351	          height={big ? 24 : 19}
352	          viewBox="0 0 24 24"
353	          fill="none"
354	          stroke={big ? NAVY : on ? NAVY : ACCENT_SOFT}
355	          strokeWidth={big ? 2.4 : 1.8}
356	          strokeLinecap="round"
357	          strokeLinejoin="round"
358	        >
359	          {path}
360	        </svg>
361	      </button>
362	    );
363	  };
364	
365	  const chip = (on: boolean, borderWidth = 1) => ({
366	    border: on
367	      ? `${borderWidth}px solid transparent`
368	      : `${borderWidth}px solid rgba(94,158,255,0.5)`,
369	    background: on ? ACTIVE : "transparent",
370	    color: on ? NAVY : ACCENT_SOFT,
371	    fontWeight: on ? 700 : 600,
372	  });
373	
374	  const reqLabel = reqFlash
375	    ? "request sent ✓"
376	    : sendRequest.isPending
377	      ? "sending…"
378	      : "send rent request";
379	  const billLabel = billFlash ? "bill sent ✓" : sendBill.isPending ? "sending…" : "send bill";
380	
381	  return (
382	    <DesktopPageScaffold {...props} vertical="property" page="terminal" showScope={false}>
383	      <style>{PT_CSS}</style>
384	      <div className="pt-body">
385	        {/* ── LEFT ── */}
386	        <div className="pt-left dt-cascade">
387	          <div>
388	            <button type="button" className="pt-scope" aria-label="all properties scope" aria-haspopup="listbox">
389	              <span>all properties</span>
390	              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6" /></svg>
391	            </button>
392	          </div>
393	
394	          <div className="pt-hero-row">
395	            <span className="pt-hero">
396	              {invoicesQuery.isLoading ? "—" : whole(model.outstandingRent)}
397	            </span>
398	          </div>
399	          <span className="pt-hero-sub">outstanding rent</span>
400	          <span className="pt-hero pt-hero-dim">
401	            {invoicesQuery.isLoading ? "—" : whole(model.outstandingExpenses)}
402	          </span>
403	          <span className="pt-hero-sub pt-hero-sub-dim">outstanding expenses</span>
404	
405	          <div className="pt-stack">
406	            <div className="pt-stack-head">
407	              <span className="pt-stack-title">
408	                <span>rent request</span>
409	                <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="m6 14 6-6 6 6" /></svg>
410	              </span>
411	              <div className="pt-stack-search">
412	                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={ACCENT} strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="6.5" /><path d="m20 20-3.8-3.8" /></svg>
413	                <input
414	                  value={search}
415	                  onChange={(e) => setSearch(e.target.value)}
416	                  placeholder="search tenants"
417	                  aria-label="search requests"
418	                />
419	              </div>
420	            </div>
421	
422	            <div className="pt-chips">
423	              {STACK_FILTERS.map((f) => (
424	                <button key={f} type="button" className="pt-chip" style={chip(f === filter)} onClick={() => setFilter(f)}>
425	                  {f}
426	                </button>
427	              ))}
428	            </div>
429	
430	            <div className="pt-rows">
431	              {invoicesQuery.isLoading ? (
432	                <div className="pt-empty">loading…</div>
433	              ) : stackRows.length === 0 ? (
434	                <div className="pt-empty">no requests here</div>
435	              ) : (
436	                stackRows.map((r) => (
437	                  <div key={r.id} className="pt-row">
438	                    <span className="pt-avatar">{r.initials}</span>
439	                    <span className="pt-row-mid">
440	                      <span className="pt-row-name">{r.name}</span>
441	                      <span className="pt-row-status">
442	                        <span className="pt-dot" style={{ background: STATUS_DOT[r.bucket] }} />
443	                        {r.status}
444	                      </span>
445	                    </span>
446	                    <span className="pt-row-amt">{r.amt}</span>
447	                  </div>
448	                ))
449	              )}
450	            </div>
451	          </div>
452	        </div>
453	
454	        {/* ── CENTER RAIL ── */}
455	        <div className="pt-rail-slot">
456	          <div className="pt-rail dt-rise" data-tutorial-id="property-terminal-tools">
457	            {railBtn("tenant", false, (<><circle cx="12" cy="8" r="3.4" /><path d="M5.5 19.5c1-3.2 3.4-4.8 6.5-4.8s5.5 1.6 6.5 4.8" /></>), "select tenant")}
458	            {railBtn("request", false, (<><path d="M22 2 11 13" /><path d="M22 2 15 22l-4-9-9-4z" /></>), "rent request")}
