831	/* mark paid */
832	.pt-paid { margin-top:100px; }
833	.pt-paid-rows { margin-top:22px; display:flex; flex-direction:column; width:440px; max-height:380px; overflow-y:auto; scrollbar-width:none; }
834	.pt-paid-rows::-webkit-scrollbar { display:none; }
