1	import { useState, useEffect, useRef } from "react";
2	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
3	import { propFetch } from "@/lib/property-api";
4	import { usePropertyTenants, usePropertyInvoices } from "@/lib/property-data";
5	import { notifyIfBillingCardRequired } from "@/lib/queryClient";
6	import {
7	  PropertyTerminalView,
8	  type PropertyTerminalScreen,
9	} from "@/features/terminal/property/PropertyTerminalView";
10	
11	const PROPERTY_TERMINAL_FONT_CSS =
12	  "@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800;900&display=swap');";
13	
14	const SUBBAR_ROUTE: Record<number, PropertyTerminalScreen> = {
15	  0: 'tenants', 1: 'send', 2: 'bill', 3: 'external',
16	};
17	
18	const CHARGE_TYPES = [
19	  { id: 'utilities', preset: 'Water / utilities' },
20	  { id: 'late_fee', preset: 'Late fee' },
21	  { id: 'cleaning', preset: 'Cleaning' },
22	  { id: 'damages', preset: 'Damages' },
23	  { id: 'other', preset: '' },
24	];
25	
26	function addInterval(from: Date, frequency: string): Date {
27	  const date = new Date(from);
28	  if (frequency === 'weekly') date.setDate(date.getDate() + 7);
29	  else if (frequency === 'fortnightly') date.setDate(date.getDate() + 14);
30	  else date.setMonth(date.getMonth() + 1);
31	  return date;
32	}
33	
34	function propHeaders(): HeadersInit {
35	  const token = localStorage.getItem('authToken');
36	  return token ? { Authorization: `Bearer ${token}` } : {};
37	}
38	
39	export default function PropertyTerminal() {
40	  const queryClient = useQueryClient();
41	
42	  /* State */
43	  const [screen, setScreen]               = useState<PropertyTerminalScreen>('home');
44	  const [selectedTenant, setSelectedTenant] = useState<any>(null);
45	  const [amount, setAmount]               = useState(0);
46	  const [conveyor, setConveyor]           = useState<any>(null);
47	  const [contentKey, setContentKey]       = useState(0);
48	  const [toastMsg, setToastMsg]           = useState<string | null>(null);
49	  const [banner, setBanner]               = useState<string | null>(null);
50	  const [successLabel, setSuccessLabel]   = useState('');
51	  const [frequency, setFrequency]         = useState('once');
52	  const [splitMode, setSplitMode]         = useState(false);
53	  const [busyScheduleId, setBusyScheduleId] = useState<string | null>(null);
54	  // When send/external/bill is tapped from subbar without a tenant, remember where to go after selection
55	  const [pendingDest, setPendingDest]     = useState<'send' | 'external' | 'bill' | null>(null);
56	  // Which screen the amount keypad returns to ('send' for rent, 'bill' for a charge)
57	  const [amountDest, setAmountDest]       = useState<'send' | 'bill'>('send');
58	  const [successKind, setSuccessKind]     = useState<'rent' | 'bill'>('rent');
59	  // Charge (Bill) draft state — lives in the parent so it survives the keypad round-trip
60	  const [chargeType, setChargeType]       = useState<string | null>(null);
61	  const [chargeLabel, setChargeLabel]     = useState('');
62	  const [dueSel, setDueSel]               = useState(7);
63	  // Optional invoice document attached to a one-off charge (uploaded ahead of send).
64	  const [chargeDocUrl, setChargeDocUrl]   = useState<string | null>(null);
65	  const [chargeDocName, setChargeDocName] = useState<string>('');
66	  const [uploadingDoc, setUploadingDoc]   = useState(false);
67	  // Tapped invoice row → action sheet (resend / mark received / cancel).
68	  const [rowAction, setRowAction]         = useState<any>(null);
69	  // Active-stack status filter + reminder mode (deep-linked from the dashboard).
70	  const [stackFilter, setStackFilter]     = useState<'all' | 'overdue' | 'sent' | 'paid' | 'failed'>('all');
71	  const [remindMode, setRemindMode]       = useState(false);
72	  const [feedOpen, setFeedOpen]           = useState(false); // rent-request feed pulled to the top of the page
73	  const conveyorTimer = useRef<ReturnType<typeof setTimeout>>();
74	
75	  /* Data — shared hooks so the stack, dashboard chart, and analytics all read
76	     the same cache entry and refresh together */
77	  const { data: tenants = [] } = usePropertyTenants();
78	  const { data: invoices = [] } = usePropertyInvoices();
79	
80	  const { data: schedules = [] } = useQuery<any[]>({
81	    queryKey: ['/api/property/schedules'],
82	    queryFn: () => propFetch('/api/property/schedules').then(r => r.ok ? r.json() : []),
83	    staleTime: 30000, retry: false,
84	  });
85	
86	  const { data: reminderSettings } = useQuery<any>({
87	    queryKey: ['/api/property/reminder-settings'],
88	    queryFn: () => propFetch('/api/property/reminder-settings').then(r => r.ok ? r.json() : null),
89	    staleTime: 60000, retry: false,
90	  });
91	
92	  /* Mutations */
93	  const sendMutation = useMutation({
94	    mutationFn: async ({ tenantId, amountCents, channel, freq, split }: any) => {
95	      const now = new Date();
96	      const due = new Date(now); due.setDate(due.getDate() + 7);
97	      // 1. Send the first request immediately
98	      const r = await fetch('/api/property/invoices', {
99	        method: 'POST', headers: { 'Content-Type': 'application/json', ...propHeaders() },
100	        body: JSON.stringify({ tenantProfileId: tenantId, amountCents, deliveryChannel: channel, dueAt: due.toISOString(), splitEnabled: !!split }),
101	      });
102	      if (!r.ok) {
103	        notifyIfBillingCardRequired(r);
104	        const message = await r.json().then((data: any) => data.message).catch(() => 'Failed to send');
105	        throw new Error(message);
106	      }
107	      const invoice = await r.json();
108	      // 2. If recurring, set up the automation starting one interval from now
109	      if (freq && freq !== 'once') {
110	        const startDate = addInterval(now, freq);
111	        const sr = await fetch(`/api/property/tenants/${tenantId}/schedules`, {
112	          method: 'POST', headers: { 'Content-Type': 'application/json', ...propHeaders() },
113	          body: JSON.stringify({ amountCents, frequency: freq, deliveryChannel: channel, startDate: startDate.toISOString() }),
114	        });
115	        if (!sr.ok) {
116	          notifyIfBillingCardRequired(sr);
117	          throw new Error('Sent, but failed to set up automation');
118	        }
119	      }
120	      return invoice;
121	    },
122	    onSuccess: (_, vars: any) => {
123	      queryClient.invalidateQueries({ queryKey: ['/api/property/invoices'] });
124	      if (vars?.freq && vars.freq !== 'once') queryClient.invalidateQueries({ queryKey: ['/api/property/schedules'] });
125	      setSuccessLabel(selectedTenant?.email || selectedTenant?.phone || '');
126	      setSuccessKind('rent');
127	      setContentKey(k => k + 1);
128	      setScreen('success');
129	      setFrequency('once');
130	      setSplitMode(false);
131	    },
132	    onError: (err: any) => { toast(err?.message || 'Failed to send'); },
133	  });
134	
135	  const billMutation = useMutation({
136	    mutationFn: async ({ tenantId, amountCents, channel, chargeType, description, dueDays, split, documentUrl, documentName }: any) => {
137	      const due = new Date(); due.setDate(due.getDate() + (dueDays || 0));
138	      const r = await fetch('/api/property/invoices', {
139	        method: 'POST', headers: { 'Content-Type': 'application/json', ...propHeaders() },
140	        body: JSON.stringify({
141	          tenantProfileId: tenantId, amountCents, deliveryChannel: channel,
142	          dueAt: due.toISOString(), splitEnabled: !!split,
143	          kind: 'charge', chargeType, description, documentUrl, documentName,
144	        }),
145	      });
146	      if (!r.ok) {
147	        notifyIfBillingCardRequired(r);
148	        const msg = await r.json().then((d: any) => d.message).catch(() => 'Failed to send bill');
149	        throw new Error(msg);
150	      }
151	      return r.json();
152	    },
153	    onSuccess: () => {
154	      queryClient.invalidateQueries({ queryKey: ['/api/property/invoices'] });
155	      setSuccessLabel(selectedTenant?.email || selectedTenant?.phone || '');
156	      setSuccessKind('bill');
157	      setContentKey(k => k + 1);
158	      setScreen('success');
159	      setSplitMode(false);
160	      setChargeDocUrl(null); setChargeDocName('');
161	    },
162	    onError: (err: any) => { toast(err?.message || 'Failed to send bill'); },
163	  });
164	
165	  const scheduleActionMutation = useMutation({
166	    mutationFn: async ({ id, action, status }: any) => {
167	      setBusyScheduleId(id);
168	      const r = action === 'cancel'
169	        ? await fetch(`/api/property/schedules/${id}`, { method: 'DELETE', headers: propHeaders() })
170	        : await fetch(`/api/property/schedules/${id}`, {
171	            method: 'PUT', headers: { 'Content-Type': 'application/json', ...propHeaders() },
172	            body: JSON.stringify({ status }),
173	          });
174	      if (!r.ok) throw new Error('Action failed');
175	      return r.json();
176	    },
177	    onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['/api/property/schedules'] }); },
178	    onError: () => { toast('Could not update automation'); },
179	    onSettled: () => { setBusyScheduleId(null); },
180	  });
181	
182	  const reminderMutation = useMutation({
183	    mutationFn: async (patch: any) => {
184	      const r = await fetch('/api/property/reminder-settings', {
185	        method: 'PUT', headers: { 'Content-Type': 'application/json', ...propHeaders() },
186	        body: JSON.stringify(patch),
187	      });
188	      if (!r.ok) throw new Error('Failed to save');
189	      return r.json();
190	    },
191	    onMutate: async (patch: any) => {
192	      await queryClient.cancelQueries({ queryKey: ['/api/property/reminder-settings'] });
193	      const prev = queryClient.getQueryData(['/api/property/reminder-settings']);
194	      queryClient.setQueryData(['/api/property/reminder-settings'], (old: any) => ({ ...(old || {}), ...patch }));
195	      return { prev };
196	    },
197	    onError: (_e, _v, ctx: any) => {
198	      if (ctx?.prev !== undefined) queryClient.setQueryData(['/api/property/reminder-settings'], ctx.prev);
199	      toast('Could not save reminders');
200	    },
201	    onSuccess: (data: any) => { queryClient.setQueryData(['/api/property/reminder-settings'], data); },
202	  });
203	
204	  const markMutation = useMutation({
205	    mutationFn: async ({ invoiceId, ref }: any) => {
206	      const r = await fetch(`/api/property/invoices/${invoiceId}/mark-paid-external`, {
207	        method: 'POST', headers: { 'Content-Type': 'application/json', ...propHeaders() },
208	        body: JSON.stringify({ externalPaymentReference: ref || null }),
209	      });
210	      if (!r.ok) throw new Error('Failed to mark');
211	      return r.json();
212	    },
213	    onSuccess: () => {
214	      queryClient.invalidateQueries({ queryKey: ['/api/property/invoices'] });
215	      setBanner('Marked as received');
216	      triggerConveyor(screen, 'down');
217	      setScreen('home');
218	      setSelectedTenant(null);
219	    },
220	  });
221	
222	  const batchMutation = useMutation({
223	    mutationFn: async (tenantIds: string[]) => {
224	      const LIVE = ['pending_dispatch', 'dispatched', 'overdue', 'dispatch_failed'];
225	      const outcomes = await Promise.all(tenantIds.map(async (tid) => {
226	        // Resend the tenant's existing live invoice — never create a duplicate.
227	        const inv = [...(invoices as any[])]
228	          .filter(i => i.tenantProfileId === tid && LIVE.includes(i.status))
229	          .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0];
230	        if (!inv) return 'skipped';
231	        try {
232	          const r = await fetch(`/api/property/invoices/${inv.id}/resend`, { method: 'POST', headers: propHeaders() });
233	          return r.ok ? 'sent' : 'failed';
234	        } catch { return 'failed'; }
235	      }));
236	      return outcomes;
237	    },
238	    onSuccess: (outcomes: string[]) => {
239	      queryClient.invalidateQueries({ queryKey: ['/api/property/invoices'] });
240	      const sent = outcomes.filter(o => o === 'sent').length;
241	      const skipped = outcomes.filter(o => o === 'skipped').length;
242	      const failed = outcomes.filter(o => o === 'failed').length;
243	      const parts = [`Resent ${sent}`];
244	      if (skipped) parts.push(`${skipped} skipped`);
245	      if (failed) parts.push(`${failed} failed`);
246	      setBanner(parts.join(' · '));
247	      triggerConveyor(screen, 'down');
248	      setScreen('home');
249	    },
250	    onError: () => { toast('Batch resend failed'); },
251	  });
252	
253	  // Cancel (void) a single invoice/charge — from the row action sheet.
254	  const voidMutation = useMutation({
255	    mutationFn: async (invoiceId: string) => {
256	      const r = await fetch(`/api/property/invoices/${invoiceId}/void`, { method: 'POST', headers: propHeaders() });
257	      if (!r.ok) {
258	        const msg = await r.json().then((d: any) => d.message).catch(() => 'Failed to cancel');
259	        throw new Error(msg);
260	      }
261	      return r.json();
262	    },
263	    onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['/api/property/invoices'] }); setBanner('Invoice cancelled'); },
264	    onError: (e: any) => { toast(e?.message || 'Could not cancel invoice'); },
265	  });
266	
267	  // Resend a single invoice's link — from the row action sheet.
268	  const resendOneMutation = useMutation({
269	    mutationFn: async (invoiceId: string) => {
270	      const r = await fetch(`/api/property/invoices/${invoiceId}/resend`, { method: 'POST', headers: propHeaders() });
271	      if (!r.ok) throw new Error('Failed to resend');
272	      return r.json();
273	    },
274	    onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['/api/property/invoices'] }); setBanner('Link resent'); },
275	    onError: () => { toast('Could not resend link'); },
276	  });
277	
278	  /* Helpers */
279	  const toast = (msg: string) => { setToastMsg(msg); setTimeout(() => setToastMsg(null), 1600); };
280	  const unpaid = (invoices as any[])
281	    .filter((i: any) => ['pending_dispatch', 'dispatched', 'overdue', 'dispatch_failed'].includes(i.status));
282	  const owing = (list: any[]) => list.reduce((s: number, i: any) => s + (i.owingCents ?? i.amountCents ?? 0), 0);
283	  const outstanding = owing(unpaid.filter((i: any) => i.kind !== 'charge'));
284	  const outstandingExpenses = owing(unpaid.filter((i: any) => i.kind === 'charge'));
285	
286	  const triggerConveyor = (prevId: PropertyTerminalScreen, dir: string) => {
287	    setConveyor({ prevId, dir });
288	    clearTimeout(conveyorTimer.current);
289	    conveyorTimer.current = setTimeout(() => setConveyor(null), 650);
290	  };
291	
292	  const go = (next: PropertyTerminalScreen, dir = 'up') => {
293	    if (next === 'home') {
294	      triggerConveyor(screen, dir);
295	      setScreen('home');
296	      setSelectedTenant(null);
297	      setAmount(0);
298	      setFrequency('once');
299	      setSplitMode(false);
300	      setPendingDest(null);
301	      setAmountDest('send');
302	      setChargeType(null);
303	      setChargeLabel('');
304	      setDueSel(7);
305	      setChargeDocUrl(null);
306	      setChargeDocName('');
307	      return;
308	    }
309	    // Send/External with no tenant: remember destination, go to tenant picker
310	    if ((next === 'send' || next === 'external') && !selectedTenant) {
311	      setPendingDest(next as 'send' | 'external');
312	      if (screen === 'home') triggerConveyor(screen, 'up');
313	      setContentKey(k => k + 1);
314	      setScreen('tenants');
315	      return;
316	    }
317	    if (screen === 'home') triggerConveyor(screen, dir);
318	    setContentKey(k => k + 1);
319	    setScreen(next);
320	  };
321	
322	  /* Dashboard deep links: ?screen=tenants|bill → jump into that flow;
323	     ?stack=overdue → home stack pre-filtered; &remind=1 → inline remind buttons.
324	     Params are consumed once, then stripped so back/refresh doesn't re-trigger. */
325	  useEffect(() => {
326	    const params = new URLSearchParams(window.location.search);
327	    const scr = params.get('screen');
328	    const stack = params.get('stack');
329	    if (!scr && !stack) return;
330	    if (scr === 'tenants') {
331	      go('tenants');
332	    } else if (scr === 'bill') {
333	      // Mirror handleSubbarPick's no-tenant bill path: pick a tenant first, then bill.
334	      setPendingDest('bill');
335	      triggerConveyor('home', 'up');
336	      setContentKey(k => k + 1);
337	      setScreen('tenants');
338	    }
339	    if (stack === 'overdue') setStackFilter('overdue');
340	    if (params.get('remind') === '1') setRemindMode(true);
341	    // Strip the params only once this instance survives: during the route
342	    // transition (Suspense + AnimatePresence) the first mount can be discarded
343	    // along with its state — stripping there starves the real mount.
344	    const strip = setTimeout(() => window.history.replaceState({}, '', window.location.pathname), 800);
345	    return () => clearTimeout(strip);
346	    // eslint-disable-next-line react-hooks/exhaustive-deps
347	  }, []);
348	
349	  const handleTenantSelect = (t: any, preAmount: number) => {
350	    setSelectedTenant(t);
351	    setContentKey(k => k + 1);
352	    // Go to the screen the user originally intended (send / external / bill), default send
353	    const dest = pendingDest || 'send';
354	    setPendingDest(null);
355	    if (dest === 'bill') {
356	      // A charge is a fresh amount — start at the keypad, then land on the bill configurator.
357	      setChargeType(null); setChargeLabel(''); setDueSel(7); setAmount(0);
358	      setChargeDocUrl(null); setChargeDocName('');
359	      setAmountDest('bill');
360	      setScreen('amount');
361	      return;
362	    }
363	    setAmount(preAmount);
364	    setScreen(dest);
365	  };
366	
367	  // Begin a charge for the already-selected tenant (from the subbar Bill tab).
368	  const startBill = () => {
369	    setChargeType(null); setChargeLabel(''); setDueSel(7); setAmount(0);
370	    setChargeDocUrl(null); setChargeDocName('');
371	    setAmountDest('bill');
372	    if (screen === 'home') triggerConveyor(screen, 'up');
373	    setContentKey(k => k + 1);
374	    setScreen('amount');
375	  };
376	
377	  // Upload the chosen invoice document, stashing the returned URL + name so the
378	  // next send attaches them. Runs immediately on file pick for instant feedback.
379	  const uploadChargeDoc = async (file: File) => {
380	    if (file.size > 20 * 1024 * 1024) { toast('file must be under 20MB'); return; }
381	    setUploadingDoc(true);
382	    try {
383	      const fd = new FormData();
384	      fd.append('document', file);
385	      const r = await fetch('/api/property/invoices/document', { method: 'POST', headers: propHeaders(), body: fd });
386	      if (!r.ok) {
387	        const msg = await r.json().then((d: any) => d.message).catch(() => 'Upload failed');
388	        throw new Error(msg);
389	      }
390	      const { documentUrl, documentName } = await r.json();
391	      setChargeDocUrl(documentUrl);
392	      setChargeDocName(documentName || file.name);
393	    } catch (err: any) {
394	      toast(err?.message || 'Failed to upload document');
395	    } finally {
396	      setUploadingDoc(false);
397	    }
398	  };
399	
400	  const clearChargeDoc = () => { setChargeDocUrl(null); setChargeDocName(''); };
401	
402	  const handleBill = () => {
403	    if (!selectedTenant) { toast('choose a tenant'); return; }
404	    if (amount === 0) { toast('set an amount first'); return; }
405	    if (!chargeType) { toast('choose what this is for'); return; }
406	    const typeDef = CHARGE_TYPES.find(c => c.id === chargeType);
407	    const description = (chargeLabel || typeDef?.preset || '').trim();
408	    if (!description) { toast('add a description'); return; }
409	    billMutation.mutate({
410	      tenantId: selectedTenant.id, amountCents: amount,
411	      channel: selectedTenant.preferredChannel || 'email',
412	      chargeType, description, dueDays: dueSel, split: splitMode,
413	      documentUrl: chargeDocUrl || undefined, documentName: chargeDocName || undefined,
414	    });
415	  };
416	
417	  // Tapping a request row opens the action sheet (resend / mark received / cancel)
418	  // — never routes a charge into the rent send flow.
419	  const handleRowTap = (inv: any) => { setRowAction(inv); };
420	
421	  // "edit amount & resend" from the sheet — opens the rent send screen pre-filled.
422	  const openEditResend = () => {
423	    const inv = rowAction;
424	    setRowAction(null);
425	    if (!inv) return;
426	    const t = (tenants as any[]).find(x => x.id === inv.tenantProfileId);
427	    if (t) {
428	      setSelectedTenant(t);
429	      setAmount(inv.amountCents ?? 0);
430	      triggerConveyor('home', 'up');
431	      setContentKey(k => k + 1);
432	      setScreen('send');
433	    }
434	  };
435	
436	  const handleVoid = () => {
437	    const inv = rowAction;
438	    if (!inv) return;
439	    if (window.confirm('Cancel this invoice? The tenant will no longer be able to pay it. This cannot be undone.')) {
440	      voidMutation.mutate(inv.id);
441	      setRowAction(null);
442	    }
443	  };
444	
445	  const handleSend = () => {
446	    if (!selectedTenant || amount === 0) { toast('set an amount first'); return; }
447	    sendMutation.mutate({ tenantId: selectedTenant.id, amountCents: amount, channel: selectedTenant.preferredChannel || 'email', freq: frequency, split: splitMode });
448	  };
449	
450	  const handleMark = (invoiceId: string, ref: string) => {
451	    markMutation.mutate({ invoiceId, ref });
452	  };
453	
454	  const handleBatch = (ids: string[]) => {
455	    batchMutation.mutate(ids);
456	  };
457	
458	  const handlePauseResume = (s: any) => {
459	    scheduleActionMutation.mutate({ id: s.id, action: 'status', status: s.status === 'paused' ? 'active' : 'paused' });
460	  };
461	
462	  const handleCancelSchedule = (s: any) => {
463	    scheduleActionMutation.mutate({ id: s.id, action: 'cancel' });
464	  };
465	
466	  /* Subbar → go shortcut (only when no tenant → redirect to tenants) */
467	  const handleSubbarPick = (i: number) => {
468	    const dest = SUBBAR_ROUTE[i];
469	    if (!dest || dest === screen) return;
470	    // Bill: with a tenant, jump straight into a fresh charge (keypad → configurator);
471	    // without one, remember the intent and pick a tenant first.
472	    if (dest === 'bill') {
473	      if (!selectedTenant) {
474	        setPendingDest('bill');
475	        if (screen === 'home') triggerConveyor(screen, 'up');
476	        setContentKey(k => k + 1);
477	        setScreen('tenants');
478	      } else {
479	        startBill();
480	      }
481	      return;
482	    }
483	    // Always open the tapped tab's own page. Send/External screens handle the
484	    // no-tenant case themselves (they show a "choose a tenant" prompt); we just
485	    // remember the intent so picking a tenant returns the user to the right page.
486	    if ((dest === 'send' || dest === 'external') && !selectedTenant) setPendingDest(dest);
487	    if (screen === 'home') triggerConveyor(screen, 'up');
488	    setContentKey(k => k + 1);
489	    setFeedOpen(false); // leaving home always lands back on the resting layout
490	    setScreen(dest);
491	  };
492	
493	  return <>
494	    <style>{PROPERTY_TERMINAL_FONT_CSS}</style>
495	    <PropertyTerminalView
496	    screen={screen}
497	    contentKey={contentKey}
498	    conveyor={conveyor}
499	    tenants={tenants as any[]}
500	    invoices={invoices as any[]}
501	    schedules={schedules}
502	    outstanding={outstanding}
503	    outstandingExpenses={outstandingExpenses}
504	    selectedTenant={selectedTenant}
505	    amount={amount}
506	    amountDest={amountDest}
507	    frequency={frequency}
508	    splitMode={splitMode}
509	    chargeType={chargeType}
510	    chargeLabel={chargeLabel}
511	    dueSel={dueSel}
512	    chargeDocUrl={chargeDocUrl}
513	    chargeDocName={chargeDocName}
514	    uploadingDoc={uploadingDoc}
515	    reminderSettings={reminderSettings}
516	    busyScheduleId={busyScheduleId}
517	    stackFilter={stackFilter}
518	    remindMode={remindMode}
519	    remindBusyId={resendOneMutation.isPending ? (resendOneMutation.variables as string) : null}
520	    feedOpen={feedOpen}
521	    successLabel={successLabel}
522	    successKind={successKind}
523	    banner={banner}
524	    toastMessage={toastMsg}
525	    rowAction={rowAction}
526	    busy={{
527	      send: sendMutation.isPending,
528	      bill: billMutation.isPending,
529	      mark: markMutation.isPending,
530	      batch: batchMutation.isPending,
531	      row: voidMutation.isPending || resendOneMutation.isPending || markMutation.isPending,
532	    }}
533	    onNavigate={go}
534	    onTenantSelect={handleTenantSelect}
535	    onAmountCommit={(amountCents, destination) => {
536	      setAmount(amountCents);
537	      go(destination);
538	    }}
539	    onEditAmount={(destination) => {
540	      setAmountDest(destination);
541	      go('amount');
542	    }}
543	    onSendRent={handleSend}
544	    onSendBill={handleBill}
545	    onFrequencyChange={setFrequency}
546	    onToggleSplit={() => setSplitMode(mode => !mode)}
547	    onChargeTypeChange={setChargeType}
548	    onChargeLabelChange={setChargeLabel}
549	    onDueChange={setDueSel}
550	    onUploadDocument={uploadChargeDoc}
551	    onClearDocument={clearChargeDoc}
552	    onStackFilterChange={setStackFilter}
553	    onRemind={(invoiceId) => resendOneMutation.mutate(invoiceId)}
554	    onToggleFeed={() => setFeedOpen(open => !open)}
555	    onRowTap={handleRowTap}
556	    onMarkExternal={handleMark}
557	    onBatchSend={handleBatch}
558	    onPauseResume={handlePauseResume}
559	    onCancelSchedule={handleCancelSchedule}
560	    onUpdateReminders={(patch) => reminderMutation.mutate(patch)}
561	    onSubbarPick={handleSubbarPick}
562	    onCloseRow={() => setRowAction(null)}
563	    onEditResend={openEditResend}
564	    onResendRow={() => {
565	      resendOneMutation.mutate(rowAction.id);
566	      setRowAction(null);
567	    }}
568	    onMarkRowReceived={() => {
569	      markMutation.mutate({ invoiceId: rowAction.id, ref: '' });
570	      setRowAction(null);
571	    }}
572	      onVoidRow={handleVoid}
573	    />
574	  </>;
575	}
