99	function SubBar({ activeIdx = -1, onPick, compact = false, hideLabel = false }: any) {
100	  const trackRef  = useRef<HTMLDivElement>(null);
101	  const btnRefs   = useRef<(HTMLElement | null)[]>([]);
102	  const mounted   = useRef(false);
103	  const [ind, setInd]       = useState({ x: 0, w: 0, on: false });
104	  const [animate, setAnim]  = useState(false);
105	
106	  const measure = (i: number) => {
107	    const el = btnRefs.current[i];
108	    if (!el) return { x: 0, w: 0 };
109	    // Use offsetLeft/offsetWidth, not getBoundingClientRect: the indicator lives
110	    // inside .tp-subbar's `transform: scale(0.85)`, so its inline left/width are in
111	    // the track's PRE-scale local space. getBoundingClientRect returns post-scale
112	    // screen pixels, which would mis-position the pill (error grows toward the right).
113	    // offsetLeft/offsetWidth are relative to the offsetParent (.tp-subbar) and unscaled.
114	    return { x: el.offsetLeft, w: el.offsetWidth };
115	  };
116	
117	  useEffect(() => {
118	    const tick = () => {
119	      if (activeIdx < 0) { setInd(p => ({ ...p, on: false })); }
120	      else { const m = measure(activeIdx); setInd({ x: m.x, w: m.w, on: true }); }
121	    };
122	    if (!mounted.current) {
123	      // Triple-RAF on first mount: wait for subbar layout + label render before measuring
124	      requestAnimationFrame(() => requestAnimationFrame(() => { tick(); mounted.current = true; }));
125	    } else {
126	      setAnim(true);
127	      // Triple-RAF on update: label renders in same commit, layout settles in 3 frames
128	      requestAnimationFrame(() => requestAnimationFrame(() => requestAnimationFrame(tick)));
129	      const t = setTimeout(() => setAnim(false), 520);
130	      return () => clearTimeout(t);
131	    }
132	  }, [activeIdx]);
133	
134	  return (
135	    <div className="tp-subbar-wrap">
136	      <div className={`tp-subbar${compact ? ' compact' : ''}`} ref={trackRef}>
137	        <div className={`tp-subbar-ind${animate ? ' animate' : ''}${ind.on ? ' on' : ''}`} style={{ left: ind.x, width: ind.w }} />
138	        {SUBBAR_ITEMS.map(({ id, label, Icon }, i) => {
139	          const active = activeIdx === i;
140	          // Active icon: light blue — visible against the navy indicator that sits above the button.
141	          // Inactive icon: dimmed navy — visible against the light-blue subbar background.
142	          const ic = active ? BLUE : 'rgba(4,13,109,0.55)';
143	          return (
144	            <button key={id} ref={(el: any) => (btnRefs.current[i] = el)}
145	              className={`tp-subbar-btn${active ? ' active' : ''}`}
146	              data-demo-id={`property-mode-${id}`}
147	              onClick={() => onPick?.(i)} aria-label={label}>
148	              <Icon sz={18} c={ic} />
149	              {active && !hideLabel && <span className="tp-subbar-label">{label}</span>}
150	            </button>
151	          );
152	        })}
153	      </div>
154	    </div>
155	  );
156	}
