1202	export function PropertyTerminalView(props: PropertyTerminalViewProps) {
1203	  const viewportRef = useRef<HTMLDivElement>(null);
1204	  const [boundaryDelta, setBoundaryDelta] = useState(0);
1205	  const isFeatureScreen = props.screen !== 'home' && props.screen !== 'success';
1206	
1207	  useEffect(() => {
1208	    if (!isFeatureScreen) { setBoundaryDelta(0); return; }
1209	    if (props.conveyor) return;
1210	    const stage = viewportRef.current;
1211	    if (!stage) return;
1212	    const measure = () => {
1213	      const layers = stage.querySelectorAll('.tp-layer');
1214	      const entering = layers[layers.length - 1];
1215	      const topPanel = entering?.querySelector('.stagger');
1216	      if (!topPanel) return;
1217	      const stageRect = stage.getBoundingClientRect();
1218	      const panelRect = topPanel.getBoundingClientRect();
1219	      setBoundaryDelta(panelRect.bottom - stageRect.top - stageRect.height / 2);
1220	    };
1221	    measure();
1222	    const observer = new ResizeObserver(measure);
1223	    stage.querySelectorAll('.tp-layer .stagger').forEach(element => observer.observe(element));
1224	    return () => observer.disconnect();
1225	  }, [isFeatureScreen, props.screen, props.conveyor]);
