/* ── Sliding indicator primitive ──────────────────────────────────────────
   Shared travel for the header nav pill and the home range pills. The base
   class owns the horizontal motion only; each call site supplies its own
   vertical placement, colour and duration, so the two remain visually distinct
   while sharing one motion contract.

   A sliding indicator is the one place a small overshoot is idiomatic, so the
   travel keeps one — but only the travel. `width` overshooting made the pill
   stretch past its label and snap back, which reads as a glitch rather than as
   spring. Same duration on both so they land together. */
.dt-slide {
  position: absolute;
  z-index: 0;
  left: 0;
  width: var(--slide-w, 0px);
  pointer-events: none;
  transition:
    transform var(--slide-dur, var(--m-dur-ui)) var(--m-ease-pop),
    width var(--slide-dur, var(--m-dur-ui)) var(--m-ease-out);
}

/* Before the first measurement the indicator must not slide in from the
   origin. Measurement happens in a layout effect, so this never costs a
   visible frame. */
.dt-slide[data-ready="false"] {
  opacity: 0;
  transition: none;
}

/* The one moving part of the header. Sits under the labels and slides between
   them; the items themselves never change size, so nothing else can shift.
   260ms is the accepted navigation duration and is deliberately not --m-dur-ui. */
.tapt-desktop-nav-bubble {
  --slide-dur: 260ms;
  top: 50%;
  height: 34px;
  border-radius: 9999px;
  background: #66a9ff;
  transform: translate(var(--slide-x, 0px), -50%);
}

/* Home range selectors. top/bottom inset by the track's own 4px padding so the
   pill matches the button box exactly at any font size, rather than pinning a
   guessed height. Range indicators run at --m-dur-ui (200ms). */
.dt-seg-indicator {
  top: 4px;
  bottom: 4px;
  border-radius: 9999px;
  transform: translateX(var(--slide-x, 0px));
}

