              width="12"
              height="12"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#7FB2FF"
              strokeWidth="2.2"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="m6 9 6 6 6-6" />
            </svg>
          </button>
        ) : null}

        <div className="tapt-desktop-page-slot">{children}</div>
      </main>
    </div>
  );
}

