1	import { useMemo, useState } from "react";
2	import { useLocation } from "wouter";
3	import { useNotifications } from "@/components/notification-system";
4	import { usePropertyInvoices, usePropertySchedules, usePropertyTenants } from "@/lib/property-data";
5	import {
6	  type Timeframe,
7	  buildBuckets,
8	  periodWindow,
9	  collectedCents,
10	  growthPct,
11	  filterByProperty,
12	} from "@/lib/property-dashboard-data";
13	import { fmtNZD } from "@/lib/report-utils";
14	import {
15	  DesktopPageScaffold,
16	  type DesktopRoutePageProps,
17	} from "../DesktopPageScaffold";
18	import { SlidingIndicator, useSlidingIndicator } from "../sliding-indicator";
19	
20	/* ── palette ── */
21	const ACCENT = "#5E9EFF";
22	const ACCENT_SOFT = "#7FB2FF";
23	const NAV_DIM = "#4A86F0";
24	const ACTIVE = "#66A9FF";
25	const TEXT_SOFT = "#F4F6FF";
26	const NAVY = "#000F3F";
27	const CHIP = "#0F1747";
28	const BAR_DIM = "rgba(94,158,255,0.32)";
29	const GREEN = "#35D07F";
30	const RED = "#F0656C";
31	const AMBER = "#F0A34E";
32	
33	const RANGES: Timeframe[] = ["day", "week", "month", "year"];
34	const RANGE_UNIT: Record<Timeframe, string> = {
35	  day: "hour",
36	  week: "day",
37	  month: "week",
38	  year: "month",
39	};
40	
41	const fmtDollars = (cents: number) => "$" + Math.round(cents / 100).toLocaleString("en-NZ");
42	
43	function initials(name: string): string {
44	  const parts = String(name ?? "")
45	    .trim()
46	    .split(/\s+/)
47	    .filter((p) => /^[a-z0-9]/i.test(p));
48	  if (parts.length === 0) return "–";
49	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
50	  return (parts[0][0] + parts[1][0]).toUpperCase();
51	}
52	
53	/* Rent invoices carry integer cents and a `dueAt`; tenants carry first/last name. */
54	const amountOf = (invoice: any) => invoice?.amountCents ?? 0;
55	const dueDateOf = (invoice: any) => invoice?.dueAt ?? invoice?.createdAt;
56	const tenantFullName = (t: any) =>
57	  `${t?.firstName ?? ""} ${t?.lastName ?? ""}`.trim() || "tenant";
58	
59	const shortDate = (v: unknown) => {
60	  if (!v) return "—";
61	  const d = new Date(String(v));
62	  return isNaN(d.getTime())
63	    ? "—"
64	    : d.toLocaleDateString("en-NZ", { day: "numeric", month: "short" }).toLowerCase();
65	};
66	
67	interface HealthStat {
68	  k: string;
69	  v: string;
70	  n: string;
71	  label: string;
72	  col: string;
73	}
74	interface DetailRow {
75	  name: string;
76	  sub: string;
77	  amt: string;
78	  col: string;
79	}
80	
81	/* Portfolio figures, chart buckets and the health strip — all derived from the
82	   shared property cache so the desktop and mobile dashboards can never
83	   disagree about a number. */
84	function usePropertyHomeModel(tf: Timeframe, selBar: number, propFilter: string | null) {
85	  const tenantsQuery = usePropertyTenants();
86	  const invoicesQuery = usePropertyInvoices();
87	  const schedulesQuery = usePropertySchedules();
88	
89	  const tenants = tenantsQuery.data ?? [];
90	  const invoices = invoicesQuery.data ?? [];
91	  const schedules = schedulesQuery.data ?? [];
92	
93	  return useMemo(() => {
94	    const { invoices: fInv, tenants: fTen } = filterByProperty(invoices, tenants, propFilter);
95	
96	    const win = periodWindow(tf);
97	    const total = collectedCents(fInv, win.start, win.end);
98	    const growth = growthPct(total, collectedCents(fInv, win.prevStart, win.prevEnd));
99	
100	    const buckets = buildBuckets(fInv, tf);
101	    const chartTotal = buckets.reduce((a, b) => a + b.valueCents, 0);
102	    const max = Math.max(...buckets.map((b) => b.valueCents), 1);
103	    let peak = 0;
104	    buckets.forEach((b, i) => {
105	      if (b.valueCents > buckets[peak].valueCents) peak = i;
106	    });
107	    const selectedIdx = selBar >= 0 && selBar < buckets.length ? selBar : peak;
108	    const selected = buckets[selectedIdx];
109	
110	    /* Portfolio health: what needs the landlord's attention right now. */
111	    const failed = fInv.filter((i: any) => i.status === "failed");
112	    const overdue = fInv.filter((i: any) => i.status === "overdue");
113	    const weekEnd = new Date();
114	    weekEnd.setDate(weekEnd.getDate() + 7);
115	    const now = new Date();
116	    const dueSoon = fInv.filter((i: any) => {
117	      if (i.status === "paid" || i.status === "paid_external" || i.status === "voided") return false;
118	      const due = new Date(dueDateOf(i));
119	      return !isNaN(due.getTime()) && due >= now && due <= weekEnd;
120	    });
121	
122	    const sum = (rows: any[]) => rows.reduce((s, i) => s + amountOf(i), 0);
123	    const tenantName = (invoice: any) => {
124	      const t = fTen.find((x: any) => x.id === invoice.tenantProfileId);
125	      return t ? tenantFullName(t) : "tenant";
126	    };
127	    const tenantAddress = (invoice: any) => {
128	      const t = fTen.find((x: any) => x.id === invoice.tenantProfileId);
129	      return t?.propertyAddress || invoice.propertyAddress || "";
130	    };
131	
132	    const health: HealthStat[] = [
133	      { k: "failed", v: fmtDollars(sum(failed)), n: String(failed.length), label: "failed", col: failed.length ? RED : TEXT_SOFT },
134	      { k: "overdue", v: fmtDollars(sum(overdue)), n: String(overdue.length), label: "overdue", col: overdue.length ? AMBER : TEXT_SOFT },
135	      { k: "due", v: fmtDollars(sum(dueSoon)), n: String(dueSoon.length), label: "due this week", col: TEXT_SOFT },
136	    ];
137	
138	    const toRows = (rows: any[], col: string): DetailRow[] =>
139	      rows.slice(0, 8).map((i: any) => ({
140	        name: tenantName(i),
141	        sub: `${tenantAddress(i) || "no address"} · ${shortDate(dueDateOf(i))}`,
142	        amt: fmtNZD(amountOf(i)),
143	        col,
144	      }));
145	
146	    const detail: Record<string, { title: string; rows: DetailRow[] }> = {
147	      failed: { title: "FAILED — RETRY OR RE-SEND", rows: toRows(failed, RED) },
148	      overdue: { title: "OVERDUE — CHASE THESE", rows: toRows(overdue, AMBER) },
149	      due: { title: "DUE IN THE NEXT 7 DAYS", rows: toRows(dueSoon, TEXT_SOFT) },
150	    };
151	
152	    /* Tenant list with each tenant's next unpaid invoice. */
153	    const recentTenants = fTen
154	      .filter((t: any) => t.status !== "archived")
155	      .map((t: any) => {
156	        const open = fInv
157	          .filter(
158	            (i: any) =>
159	              i.tenantProfileId === t.id &&
160	              i.status !== "paid" &&
161	              i.status !== "paid_external" &&
162	              i.status !== "voided",
163	          )
164	          .sort(
165	            (a: any, b: any) =>
166	              new Date(dueDateOf(a)).getTime() - new Date(dueDateOf(b)).getTime(),
167	          );
168	        const next = open[0];
169	        const schedule = schedules.find((s: any) => s.tenantProfileId === t.id);
170	        return {
171	          id: t.id,
172	          name: tenantFullName(t),
173	          address: t.propertyAddress || "no address",
174	          amt: next
175	            ? fmtNZD(amountOf(next))
176	            : schedule
177	              ? fmtNZD(schedule.amountCents ?? 0)
178	              : "—",
179	          due: next ? shortDate(dueDateOf(next)) : schedule ? "scheduled" : "nothing due",
180	          sortKey: next ? new Date(dueDateOf(next)).getTime() : Number.MAX_SAFE_INTEGER,
181	        };
182	      })
183	      .sort((a, b) => a.sortKey - b.sortKey);
184	
185	    const addresses = Array.from(
186	      new Set(tenants.map((t: any) => t.propertyAddress).filter(Boolean)),
187	    ) as string[];
