/* ── Desktop list entrance ────────────────────────────────────────────────
   Named tablet/desktop lists (transaction history, live stock tiles, the
   Property/Trades directories, and in Phase 2 the active stack) enter with a
   short rise instead of the opacity-only row tier. This is a deliberate,
   limited override of that one tier in docs/PLAN-2026-08-15-motion-toning.md;
   page, panel, modal, navigation and phone motion are untouched.

   Transform and opacity are separate animations on purpose. --m-ease-list
   carries a ~1.25% scalar overshoot, which is right for travel and wrong for
   opacity — an overshooting fade clamps at 1 and reads as a flicker. */
.tapt-desktop-viewport {
  --m-dur-list: 440ms;
  --m-stagger-list: 40ms;
  --m-ease-list: cubic-bezier(0.34, 1.2, 0.64, 1);
}

@keyframes dtListRise {
  from {
    transform: translateY(8px);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes dtListFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

