import { BASE_URL, newRetailPage, CHROMIUM_PATH } from "/home/runner/workspace/scripts/desktop-shots/retail-fixtures.mjs";
import { chromium } from "playwright";

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
const { context, page } = await newRetailPage(browser, "desktop", { viewport: { width: 1440, height: 900 } });
await page.goto(`${BASE_URL}/terminal`, { waitUntil: "networkidle" });
await page.waitForTimeout(1500);

const read = async () => page.evaluate(() => {
  const canvas = document.querySelector("[data-desktop-scale]");
  const scale = parseFloat(canvas.dataset.desktopScale) || 1;
  const o = canvas.getBoundingClientRect();
  const m = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return {
      x: +((r.left - o.left) / scale).toFixed(1),
      y: +((r.top - o.top) / scale).toFixed(1),
      w: +(r.width / scale).toFixed(1),
      h: +(r.height / scale).toFixed(1),
      bottom: +((r.bottom - o.top) / scale).toFixed(1),
    };
  };
  return {
    rail: m(".terminal-rail"),
    zoneA: m(".terminal-zone-a"),
    zoneB: m(".terminal-zone-b"),
    zoneC: m(".terminal-zone-c"),
    head: m(".rt-stack-head"),
    search: m(".rt-stack-search"),
    chips: m(".rt-chips"),
    rows: m(".rt-rows"),
  };
});

console.log("── SEND (collapsed) ──");
console.log(JSON.stringify(await read(), null, 1));

await page.getByRole("button", { name: "expand active stack" }).click();
await page.waitForTimeout(400);
const exp = await read();
console.log("── EXPANDED stack ──");
console.log(JSON.stringify({ head: exp.head, search: exp.search, chips: exp.chips, rows: exp.rows }, null, 1));

await context.close();
await browser.close();
EOF
